// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 deposit, uint256 amount) public {
        vm.assume(deposit <= VALUE_CAP);
        deposit = bound(deposit, 1 ether, 10 ether);
        amount = bound(amount, 1 ether, deposit);

        address actor = address(0xBEEF);
        ReentrantCollector attacker = new ReentrantCollector(address(c), amount);

        vm.deal(address(attacker), deposit);
        attacker.deposit{value: deposit}(0);

        vm.warp(block.timestamp + 1);

        uint256 beforeBal = attacker.balanceOf();
        uint256 beforeEth = address(c).balance;

        try attacker.attack{gas: 1000000}() {} catch {}

        uint256 afterBal = attacker.balanceOf();
        uint256 afterEth = address(c).balance;

        uint256 balanceDrop = beforeBal > afterBal ? beforeBal - afterBal : 0;
        uint256 ethDrop = beforeEth > afterEth ? beforeEth - afterEth : 0;

        assertTrue(
            ethDrop <= amount || balanceDrop <= amount,
            "reentrancy allowed: balance decreased by more than one Collect amount"
        );
    }

    receive() external payable {}
}

contract ReentrantCollector {
    MY_BANK private c;
    uint256 private attackAmount;
    bool private entered;

    constructor(address _c, uint256 _amount) {
        c = MY_BANK(payable(_c));
        attackAmount = _amount;
    }

    function deposit(uint256 unlockTime) external payable {
        c.Put{value: msg.value}(unlockTime);
    }

    function attack() external {
        c.Collect(attackAmount);
    }

    function balanceOf() external view returns (uint256) {
        ( , uint256 bal) = c.Acc(address(this));
        return bal;
    }

    receive() external payable {
        if (!entered && address(c).balance >= attackAmount) {
            entered = true;
            c.Collect(attackAmount);
        }
    }
}
